void GpuSpheres::reset(const std::vector<Particle>& particles){auto& x=*impl_;validate_particles(particles);require(!particles.empty(),"empty GPU charge");require(gpu_memory_plan(particles.size()).total_bytes<=x.budget,"GPU state exceeds configured budget");std::set<ParticleId> ids;for(const auto& p:particles)require(ids.insert(p.id).second,"duplicate GPU ID");
 std::array<std::vector<V>,4> host;for(auto& v:host)v.reserve(particles.size());for(const auto& p:particles){const auto props=sphere_properties(p.diameter_m,p.material);host[0].push_back({p.position_m.x,p.position_m.y,p.position_m.z,props.radius_m});host[1].push_back({p.velocity_m_s.x,p.velocity_m_s.y,p.velocity_m_s.z,props.mass_kg});host[2].push_back({p.angular_velocity_rad_s.x,p.angular_velocity_rad_s.y,p.angular_velocity_rad_s.z,props.inertia_kg_m2});host[3].push_back({p.orientation.w,p.orientation.x,p.orientation.y,p.orientation.z});}
 const auto start=Clock::now();std::array<cl_mem,8> next{};try{for(auto& b:next)b=x.allocate(particles.size()*sizeof(V));for(unsigned i=0;i<4;++i)x.write(next[i],host[i].size()*sizeof(V),host[i].data());}catch(...){for(auto b:next)if(b)x.api.clReleaseMemObject(b);throw;}
 for(auto b:x.state)if(b)x.api.clReleaseMemObject(b);x.clear_contacts();x.state=next;x.original=particles;x.time=0;x.poisoned=false;x.report_valid=false;cl_int zero=0;x.write(x.error,sizeof(zero),&zero);x.times.upload_wall_s+=elapsed(start);
}
void GpuSpheres::advance_free(double dt,std::uint32_t steps,Vec3 gravity,Vec3 force){auto& x=*impl_;require(!x.original.empty(),"GPU state not initialized");require(!x.contacts_enabled,"free advance forbidden for configured contact scene");require(std::isfinite(dt)&&dt>0&&steps>0&&steps<=1000000&&std::isfinite(x.time+dt*steps),"invalid GPU free advance");for(double value:{gravity.x,gravity.y,gravity.z,force.x,force.y,force.z})require(std::isfinite(value),"nonfinite external load");
 require(!x.poisoned,"GPU device state uncertain; reset required");x.poisoned=true;const auto start=Clock::now();const cl_uint n=static_cast<cl_uint>(x.original.size());for(cl_uint i=0;i<8;++i){x.arg(x.free_kernel,i,x.state[i]);x.arg(x.commit,i,x.state[i]);}x.arg(x.free_kernel,8,n);x.arg(x.free_kernel,9,dt);x.arg(x.free_kernel,10,steps);const V g{gravity.x,gravity.y,gravity.z,0},f{force.x,force.y,force.z,0};x.arg(x.free_kernel,11,g);x.arg(x.free_kernel,12,f);x.arg(x.free_kernel,13,x.error);x.arg(x.commit,8,n);x.arg(x.commit,9,x.error);
 cl_int status=0;x.write(x.error,sizeof(status),&status);auto event=x.launch(x.free_kernel,n);auto commit_event=x.launch(x.commit,n);check(x.api.clFinish(x.queue),"finish free batch");x.times.compute_gpu_s+=x.event_seconds(event)+x.event_seconds(commit_event);x.read(x.error,sizeof(status),&status);x.times.compute_wall_s+=elapsed(start);x.poisoned=false;if(status)throw std::runtime_error("GPU free step rejected before commit: "+std::to_string(status));x.time+=dt*steps;
}
