 x.arg(guard,0,x.state[4]);x.arg(guard,1,x.extra[1]);x.arg(guard,2,n);x.arg(guard,3,x.cell);x.arg(guard,4,x.candidates);x.arg(guard,5,x.error);x.arg(guard,6,x.wall_state[0]);x.arg(guard,7,wall_count);x.arg(guard,9,x.state[0]);x.arg(guard,10,dt);
